insert into public.menu_templates (slug, name, segment, description, preview_image_url, tier, version, default_theme, demo_document, sort_order) values
  ('royal-gold', 'Royal Gold', 'Restaurantes de luxo e steakhouses', 'Preto profundo, dourado e fotografias amplas. Uma carta para casas de alta gastronomia.', 'https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=1200&q=72', 'premium', 1, '{"colors":{"primary":"#C9A55C","secondary":"#8C7340","background":"#0A0A0A","text":"#E8E2D6","heading":"#F3E7C9","button":"#C9A55C","buttonText":"#0A0A0A","border":"#2E2A22","card":"#141311","highlight":"#E3C786","header":"#0A0A0A","footer":"#050505"},"fonts":{"heading":"cinzel","body":"cormorant","headingScale":1,"bodyScale":1.08,"headingWeight":400,"letterSpacing":0.08},"layout":{"productView":"large","imagePosition":"top","radius":2,"spacing":"airy","showImages":true,"showDescriptions":true,"buttonStyle":"outline","headerStyle":"hero"}}'::jsonb, '{"establishment":{"name":"Maison Aurum","tagline":"Alta gastronomia e cortes nobres","description":"Cozinha autoral com brasa e técnica clássica. Carnes maturadas na casa, adega com mais de 300 rótulos e serviço à francesa.","coverUrl":"https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&w=1600&q=72","phone":"(62) 3000-0101","whatsapp":"5500000000000","address":"Av. das Palmeiras, 1200 — Setor Jardins, Goiânia - GO","instagram":"@maisonaurum.demo","hours":[{"days":"Terça a sábado","hours":"19h – 00h"},{"days":"Domingo","hours":"12h – 16h"}],"extraInfo":"Traje esporte fino. Reservas recomendadas para jantares de sexta e sábado."},"settings":{"whatsappOrders":false,"whatsappButton":true,"showSearch":true,"demo":true},"categories":[{"id":"entradas","name":"Entradas","products":[{"id":"steak-tartare","name":"Steak tartare","description":"Filé-mignon picado na ponta da faca, gema curada, alcaparras e torradas de brioche.","priceCents":8900,"imageUrl":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=72","ingredients":["filé-mignon","gema curada","alcaparras","chalota","mostarda Dijon","brioche"],"featured":true,"available":true,"allergens":["ovo","gluten"]},{"id":"carpaccio-de-wagyu","name":"Carpaccio de wagyu","description":"Lâminas finas de wagyu, rúcula selvagem, parmesão de 24 meses e azeite trufado.","priceCents":11200,"imageUrl":"https://images.unsplash.com/photo-1540189549336-e6e99c3679fe?auto=format&fit=crop&w=900&q=72","available":true,"allergens":["lactose"]},{"id":"burrata-com-tomates-confitados","name":"Burrata com tomates confitados","description":"Burrata cremosa, tomates de três cores confitados e pesto de manjericão.","priceCents":7600,"imageUrl":"https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=900&q=72","available":true,"tags":["Vegetariano"],"allergens":["lactose","castanhas"]},{"id":"vieiras-na-manteiga-noisette","name":"Vieiras na manteiga noisette","description":"Vieiras seladas, purê de couve-flor e farofa de avelã.","priceCents":11800,"imageUrl":"https://images.unsplash.com/photo-1565680018434-b513d5e5fd47?auto=format&fit=crop&w=900&q=72","available":true,"allergens":["crustaceos","lactose","castanhas"]}]},{"id":"cortes-especiais","name":"Cortes especiais","description":"Selecionados e maturados na casa. Escolha o ponto com o garçom.","products":[{"id":"tomahawk-maturado-45-dias","name":"Tomahawk maturado 45 dias","description":"Corte com osso, maturado na casa, finalizado na brasa de lenha frutífera.","priceCents":48900,"imageUrl":"https://images.unsplash.com/photo-1600891964092-4316c288032e?auto=format&fit=crop&w=900&q=72","notes":"Tempo de preparo: 35 minutos.","featured":true,"available":true,"tags":["1,2 kg","Serve 2"]},{"id":"file-rossini","name":"Filé Rossini","description":"Medalhão de filé, foie gras selado, molho Périgueux e brioche tostado.","priceCents":24800,"imageUrl":"https://images.unsplash.com/photo-1558030006-450675393462?auto=format&fit=crop&w=900&q=72","available":true,"allergens":["gluten","lactose"]},{"id":"ancho-black-angus","name":"Ancho Black Angus","description":"Corte suculento e marmorizado, servido com flor de sal e chimichurri da casa.","priceCents":19800,"imageUrl":"https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=900&q=72","available":true,"variations":[{"id":"ancho-black-angus-v-300-g","name":"300 g","priceCents":19800},{"id":"ancho-black-angus-v-450-g","name":"450 g","priceCents":26800}]},{"id":"wagyu-a5-japones","name":"Wagyu A5 japonês","description":"Seleção limitada, servida em pedra quente com sal defumado.","priceCents":69000,"imageUrl":"https://images.unsplash.com/photo-1600891964092-4316c288032e?auto=format&fit=crop&w=900&q=72","available":false,"tags":["150 g"]}]},{"id":"acompanhamentos","name":"Acompanhamentos","products":[{"id":"batatas-souffle","name":"Batatas soufflé","description":"Clássico francês, crocantes e aeradas.","priceCents":4200,"imageUrl":"https://images.unsplash.com/photo-1573080496219-bb080dd4f877?auto=format&fit=crop&w=900&q=72","available":true},{"id":"pure-trufado","name":"Purê trufado","description":"Batata-baroa, manteiga de Isigny e trufa negra ralada.","priceCents":5800,"available":true,"allergens":["lactose"]},{"id":"aspargos-grelhados","name":"Aspargos grelhados","description":"Aspargos verdes, hollandaise e amêndoas laminadas.","priceCents":5400,"available":true,"allergens":["ovo","castanhas"]},{"id":"arroz-de-alho-negro","name":"Arroz de alho negro","description":"Arroz cremoso com alho negro fermentado e parmesão.","priceCents":4600,"available":true,"allergens":["lactose"]}]},{"id":"sobremesas","name":"Sobremesas","products":[{"id":"souffle-de-chocolate-70","name":"Soufflé de chocolate 70%","description":"Preparado na hora, com sorvete de baunilha de Madagascar.","priceCents":6400,"imageUrl":"https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=900&q=72","notes":"Preparo de 20 minutos.","featured":true,"available":true,"allergens":["ovo","lactose","gluten"]},{"id":"creme-brulee-de-fava-tonka","name":"Crème brûlée de fava tonka","description":"Creme sedoso com crosta caramelizada no maçarico.","priceCents":4800,"imageUrl":"https://images.unsplash.com/photo-1565958011703-44f9829ba187?auto=format&fit=crop&w=900&q=72","available":true,"allergens":["ovo","lactose"]},{"id":"pavlova-de-frutas-vermelhas","name":"Pavlova de frutas vermelhas","description":"Merengue crocante, chantilly e frutas da estação.","priceCents":5200,"imageUrl":"https://images.unsplash.com/photo-1488477181946-6428a0291777?auto=format&fit=crop&w=900&q=72","available":true,"allergens":["ovo","lactose"]}]},{"id":"bebidas","name":"Bebidas","products":[{"id":"champagne-brut-taca","name":"Champagne Brut — taça","description":"Seleção do sommelier.","priceCents":8900,"imageUrl":"https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?auto=format&fit=crop&w=900&q=72","available":true},{"id":"malbec-reserva-garrafa","name":"Malbec reserva — garrafa","description":"Mendoza, notas de ameixa, violeta e carvalho tostado.","priceCents":34000,"imageUrl":"https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?auto=format&fit=crop&w=900&q=72","available":true},{"id":"negroni","name":"Negroni","description":"Gin, vermute rosso e bitter italiano.","priceCents":5200,"imageUrl":"https://images.unsplash.com/photo-1514362545857-3bc16c4c7d1b?auto=format&fit=crop&w=900&q=72","available":true},{"id":"agua-mineral","name":"Água mineral","description":"Com ou sem gás, 500 ml.","priceCents":1400,"available":true}]}]}'::jsonb, 0),
  ('pure-minimal', 'Pure Minimal', 'Bistrôs e cafeterias premium', 'Branco, areia e muito respiro. O texto conduz e as fotos aparecem só onde importam.', 'https://images.unsplash.com/photo-1482049016688-2d3e1b311543?auto=format&fit=crop&w=1200&q=72', 'essential', 1, '{"colors":{"primary":"#2B2A27","secondary":"#A8987C","background":"#FBFAF7","text":"#3A3833","heading":"#1F1E1B","button":"#2B2A27","buttonText":"#FBFAF7","border":"#E6E1D7","card":"#FFFFFF","highlight":"#B9A27A","header":"#FBFAF7","footer":"#F2EEE6"},"fonts":{"heading":"manrope","body":"manrope","headingScale":1,"bodyScale":1,"headingWeight":300,"letterSpacing":-0.01},"layout":{"productView":"list","imagePosition":"side","radius":6,"spacing":"airy","showImages":true,"showDescriptions":true,"buttonStyle":"solid","headerStyle":"minimal"}}'::jsonb, '{"establishment":{"name":"Atelier Areia","tagline":"Café, brunch e cozinha de estação","description":"Bistrô de bairro com pães de fermentação natural, cafés especiais e pratos que mudam com a feira da semana.","coverUrl":"https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1600&q=72","phone":"(62) 3000-0202","whatsapp":"5500000000000","address":"Rua das Acácias, 88 — Setor Oeste, Goiânia - GO","instagram":"@atelierareia.demo","hours":[{"days":"Terça a sexta","hours":"8h – 18h"},{"days":"Sábado e domingo","hours":"8h – 15h"}]},"settings":{"whatsappOrders":true,"whatsappButton":true,"showSearch":true,"demo":true},"categories":[{"id":"cafes","name":"Cafés","products":[{"id":"espresso","name":"Espresso","description":"Blend da casa, notas de caramelo e cacau.","priceCents":800,"imageUrl":"https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=900&q=72","available":true,"variations":[{"id":"espresso-v-simples","name":"Simples","priceCents":800},{"id":"espresso-v-duplo","name":"Duplo","priceCents":1200}]},{"id":"flat-white","name":"Flat white","description":"Espresso duplo e leite vaporizado em microespuma.","priceCents":1600,"imageUrl":"https://images.unsplash.com/photo-1541167760496-1628856ab772?auto=format&fit=crop&w=900&q=72","available":true,"allergens":["lactose"],"addons":[{"id":"flat-white-a-leite-de-aveia","name":"Leite de aveia","priceCents":300},{"id":"flat-white-a-dose-extra","name":"Dose extra","priceCents":500}]},{"id":"coado-do-dia","name":"Coado do dia","description":"Método V60 com grão especial da semana. Pergunte a origem.","priceCents":1400,"imageUrl":"https://images.unsplash.com/photo-1559056199-641a0ac8b55e?auto=format&fit=crop&w=900&q=72","featured":true,"available":true},{"id":"cold-brew","name":"Cold brew","description":"Extração a frio por 18 horas, servido com gelo.","priceCents":1700,"imageUrl":"https://images.unsplash.com/photo-1461023058943-07fcbe16d735?auto=format&fit=crop&w=900&q=72","available":true}]},{"id":"brunch","name":"Brunch","products":[{"id":"ovos-mexidos-cremosos","name":"Ovos mexidos cremosos","description":"Ovos caipiras, ciboulette e pão de fermentação natural.","priceCents":3800,"imageUrl":"https://images.unsplash.com/photo-1482049016688-2d3e1b311543?auto=format&fit=crop&w=900&q=72","featured":true,"available":true,"allergens":["ovo","gluten","lactose"],"addons":[{"id":"ovos-mexidos-cremosos-a-bacon-crocante","name":"Bacon crocante","priceCents":900},{"id":"ovos-mexidos-cremosos-a-abacate","name":"Abacate","priceCents":700}]},{"id":"tartine-de-abacate","name":"Tartine de abacate","description":"Abacate, limão-siciliano, rabanete e sementes tostadas.","priceCents":3600,"imageUrl":"https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=900&q=72","available":true,"tags":["Vegano"],"allergens":["gluten","gergelim"]},{"id":"panqueca-de-ricota","name":"Panqueca de ricota","description":"Panquecas altas, ricota fresca, frutas vermelhas e mel.","priceCents":3400,"imageUrl":"https://images.unsplash.com/photo-1488477181946-6428a0291777?auto=format&fit=crop&w=900&q=72","available":true,"allergens":["ovo","lactose","gluten"]},{"id":"granola-da-casa","name":"Granola da casa","description":"Iogurte natural, granola artesanal e frutas da estação.","priceCents":2600,"imageUrl":"https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=900&q=72","available":true,"allergens":["lactose","castanhas"]}]},{"id":"pratos-artesanais","name":"Pratos artesanais","products":[{"id":"risoto-de-cogumelos","name":"Risoto de cogumelos","description":"Arroz arbóreo, mix de cogumelos frescos e parmesão.","priceCents":6200,"imageUrl":"https://images.unsplash.com/photo-1563379926898-05f4575a45d8?auto=format&fit=crop&w=900&q=72","available":true,"allergens":["lactose"]},{"id":"salmao-com-legumes","name":"Salmão com legumes","description":"Salmão grelhado, legumes assados e molho de ervas.","priceCents":7200,"imageUrl":"https://images.unsplash.com/photo-1467003909585-2f8a72700288?auto=format&fit=crop&w=900&q=72","available":true,"allergens":["peixe"]},{"id":"bowl-de-graos","name":"Bowl de grãos","description":"Quinoa, grão-de-bico, legumes tostados e tahine.","priceCents":4400,"imageUrl":"https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=900&q=72","available":true,"tags":["Vegano"],"allergens":["gergelim"]}]},{"id":"sobremesas","name":"Sobremesas","products":[{"id":"bolo-de-laranja","name":"Bolo de laranja","description":"Fatia generosa com calda de laranja-baía.","priceCents":1800,"imageUrl":"https://images.unsplash.com/photo-1565958011703-44f9829ba187?auto=format&fit=crop&w=900&q=72","available":true,"allergens":["ovo","gluten","lactose"]},{"id":"cookie-de-chocolate","name":"Cookie de chocolate","description":"Massa amanteigada com chocolate 54%.","priceCents":1400,"imageUrl":"https://images.unsplash.com/photo-1558961363-fa8fdf82db35?auto=format&fit=crop&w=900&q=72","available":true,"allergens":["gluten","lactose","ovo"]},{"id":"croissant-de-amendoas","name":"Croissant de amêndoas","description":"Massa folhada na manteiga e creme de