  ('urban-black', 'Urban Black', 'Hamburguerias gourmet', 'Tipografia condensada, vermelho intenso e fotos que ocupam o card inteiro. Feito para dar fome.', 'https://images.unsplash.com/photo-1550547660-d9450f859349?auto=format&fit=crop&w=1200&q=72', 'essential', 1, '{"colors":{"primary":"#C8102E","secondary":"#7A0A1C","background":"#0E0E0E","text":"#EDEDED","heading":"#FFFFFF","button":"#C8102E","buttonText":"#FFFFFF","border":"#2A2A2A","card":"#181818","highlight":"#FFC93C","header":"#0E0E0E","footer":"#000000"},"fonts":{"heading":"bebas","body":"inter","headingScale":1.1,"bodyScale":0.95,"headingWeight":400,"letterSpacing":0.02},"layout":{"productView":"grid","imagePosition":"top","radius":14,"spacing":"normal","showImages":true,"showDescriptions":true,"buttonStyle":"solid","headerStyle":"hero"}}'::jsonb, '{"establishment":{"name":"Brasa Street Burger","tagline":"Smash na chapa, pão brioche e molho da casa","description":"Hamburgueria de bairro com blends próprios moídos todo dia e chapa de ferro fundido.","coverUrl":"https://images.unsplash.com/photo-1586190848861-99aa4a171e90?auto=format&fit=crop&w=1600&q=72","phone":"(62) 3000-0303","whatsapp":"5500000000000","address":"Rua T-55, 410 — Setor Bueno, Goiânia - GO","instagram":"@brasastreet.demo","hours":[{"days":"Segunda a quinta","hours":"18h – 23h"},{"days":"Sexta a domingo","hours":"18h – 01h"}]},"settings":{"whatsappOrders":true,"whatsappButton":true,"showSearch":true,"demo":true},"categories":[{"id":"hamburgueres","name":"Hambúrgueres","products":[{"id":"brasa-classic","name":"Brasa Classic","description":"Blend 160 g, cheddar inglês, picles, cebola e molho Brasa no brioche.","priceCents":3400,"imageUrl":"https://images.unsplash.com/photo-1550547660-d9450f859349?auto=format&fit=crop&w=900&q=72","featured":true,"available":true,"tags":["Mais pedido"],"allergens":["gluten","lactose","ovo"],"addons":[{"id":"brasa-classic-a-bacon","name":"Bacon","priceCents":600},{"id":"brasa-classic-a-cheddar-extra","name":"Ch